SELECT setval(pg_get_serial_sequence('menus', 'id'), GREATEST((SELECT MAX(id) FROM menus), 1));

-- Department -> module grants, to every employee of the department.
-- Additive: existing employee_menu rows are kept, duplicates skipped.
--   OPERATIONS: SALES, STORES, PRODUCTION, DESPATCH, QUALITY ASSURANCE, SUPPLY CHAIN, IMPORT, MANAGEMENT
--   DISPATCH: DESPATCH, STORES
--   ADMINISTRATION - FACTORY: HR OPERATIONS, FIXED ASSETS, STORES, SUPPLY CHAIN
--   PLANT: PRODUCTION, LAB, QUALITY ASSURANCE
--   BOILER: PRODUCTION
--   SECURITY: DESPATCH
--   FINANCE: FINANCE, IMPORT, FIXED ASSETS, SALES, STORES, MANAGEMENT
--   DRAWINGS: SALES, LAB, STORES, PRODUCTION, DESPATCH, FINANCE, ACCOUNTS DESK, IMPORT, HR OPERATIONS, FIXED ASSETS, MANAGEMENT, QUALITY ASSURANCE, SUPPLY CHAIN
--   SMS INDUSTRIES DISTILLERY: PRODUCTION, LAB, QUALITY ASSURANCE, STORES
--   ACCOUNTS: FINANCE, IMPORT, FIXED ASSETS
--   GENERAL ADMINISTRATION - HO: HR OPERATIONS, MANAGEMENT, FIXED ASSETS
--   SALES: SALES, DESPATCH
INSERT INTO employee_menu (employee_id, menu_id)
SELECT e.id, m.id
FROM "Employee" e
JOIN "Department" d ON d.id = e."departmentId"
JOIN (VALUES
  ('OPERATIONS', 'SALES'),
  ('OPERATIONS', 'STORES'),
  ('OPERATIONS', 'PRODUCTION'),
  ('OPERATIONS', 'DESPATCH'),
  ('OPERATIONS', 'QUALITY ASSURANCE'),
  ('OPERATIONS', 'SUPPLY CHAIN'),
  ('OPERATIONS', 'IMPORT'),
  ('OPERATIONS', 'MANAGEMENT'),
  ('DISPATCH', 'DESPATCH'),
  ('DISPATCH', 'STORES'),
  ('ADMINISTRATION - FACTORY', 'HR OPERATIONS'),
  ('ADMINISTRATION - FACTORY', 'FIXED ASSETS'),
  ('ADMINISTRATION - FACTORY', 'STORES'),
  ('ADMINISTRATION - FACTORY', 'SUPPLY CHAIN'),
  ('PLANT', 'PRODUCTION'),
  ('PLANT', 'LAB'),
  ('PLANT', 'QUALITY ASSURANCE'),
  ('BOILER', 'PRODUCTION'),
  ('SECURITY', 'DESPATCH'),
  ('FINANCE', 'FINANCE'),
  ('FINANCE', 'IMPORT'),
  ('FINANCE', 'FIXED ASSETS'),
  ('FINANCE', 'SALES'),
  ('FINANCE', 'STORES'),
  ('FINANCE', 'MANAGEMENT'),
  ('DRAWINGS', 'SALES'),
  ('DRAWINGS', 'LAB'),
  ('DRAWINGS', 'STORES'),
  ('DRAWINGS', 'PRODUCTION'),
  ('DRAWINGS', 'DESPATCH'),
  ('DRAWINGS', 'FINANCE'),
  ('DRAWINGS', 'ACCOUNTS DESK'),
  ('DRAWINGS', 'IMPORT'),
  ('DRAWINGS', 'HR OPERATIONS'),
  ('DRAWINGS', 'FIXED ASSETS'),
  ('DRAWINGS', 'MANAGEMENT'),
  ('DRAWINGS', 'QUALITY ASSURANCE'),
  ('DRAWINGS', 'SUPPLY CHAIN'),
  ('SMS INDUSTRIES DISTILLERY', 'PRODUCTION'),
  ('SMS INDUSTRIES DISTILLERY', 'LAB'),
  ('SMS INDUSTRIES DISTILLERY', 'QUALITY ASSURANCE'),
  ('SMS INDUSTRIES DISTILLERY', 'STORES'),
  ('ACCOUNTS', 'FINANCE'),
  ('ACCOUNTS', 'IMPORT'),
  ('ACCOUNTS', 'FIXED ASSETS'),
  ('GENERAL ADMINISTRATION - HO', 'HR OPERATIONS'),
  ('GENERAL ADMINISTRATION - HO', 'MANAGEMENT'),
  ('GENERAL ADMINISTRATION - HO', 'FIXED ASSETS'),
  ('SALES', 'SALES'),
  ('SALES', 'DESPATCH')
) AS g(dept_name, module) ON g.dept_name = d.dept_name
JOIN menus m ON m.title = g.module AND m.parent_id IS NULL
WHERE e.id NOT IN (98, 141, 169, 178, 179)
ON CONFLICT (employee_id, menu_id) DO NOTHING;

-- People with their own menu list: exactly these entries.
DELETE FROM employee_menu WHERE employee_id = 98 AND menu_id NOT IN (215, 219, 220, 225, 229, 233, 237);
INSERT INTO employee_menu (employee_id, menu_id) SELECT 98, id FROM menus WHERE id IN (215, 219, 220, 225, 229, 233, 237)
  AND EXISTS (SELECT 1 FROM "Employee" WHERE id = 98) ON CONFLICT (employee_id, menu_id) DO NOTHING;
DELETE FROM employee_menu WHERE employee_id = 141 AND menu_id NOT IN (215, 219, 220, 225, 229, 233, 237);
INSERT INTO employee_menu (employee_id, menu_id) SELECT 141, id FROM menus WHERE id IN (215, 219, 220, 225, 229, 233, 237)
  AND EXISTS (SELECT 1 FROM "Employee" WHERE id = 141) ON CONFLICT (employee_id, menu_id) DO NOTHING;
DELETE FROM employee_menu WHERE employee_id = 169 AND menu_id NOT IN (229, 233, 237);
INSERT INTO employee_menu (employee_id, menu_id) SELECT 169, id FROM menus WHERE id IN (229, 233, 237)
  AND EXISTS (SELECT 1 FROM "Employee" WHERE id = 169) ON CONFLICT (employee_id, menu_id) DO NOTHING;
DELETE FROM employee_menu WHERE employee_id = 178 AND menu_id NOT IN (215, 219, 220, 225, 229, 233, 237);
INSERT INTO employee_menu (employee_id, menu_id) SELECT 178, id FROM menus WHERE id IN (215, 219, 220, 225, 229, 233, 237)
  AND EXISTS (SELECT 1 FROM "Employee" WHERE id = 178) ON CONFLICT (employee_id, menu_id) DO NOTHING;
DELETE FROM employee_menu WHERE employee_id = 179 AND menu_id NOT IN (216, 217, 219, 220, 225, 229, 233, 237);
INSERT INTO employee_menu (employee_id, menu_id) SELECT 179, id FROM menus WHERE id IN (216, 217, 219, 220, 225, 229, 233, 237)
  AND EXISTS (SELECT 1 FROM "Employee" WHERE id = 179) ON CONFLICT (employee_id, menu_id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('employee_menu', 'id'), GREATEST((SELECT MAX(id) FROM employee_menu), 1));

COMMIT;
